MOD = 10**9 + 7

def count_ways(n, k):
    # Initialize memoization table
    memo = {}

    def dp(row, col, min_row, min_col):
        if (row, col, min_row, min_col) in memo:
            return memo[(row, col, min_row, min_col)]

        if row == n:
            # If we've filled all rows, check if the last column satisfies the condition
            return 1 if min_col <= k else 0

        if col == n:
            # If we've filled all columns in the current row, move to the next row
            return dp(row + 1, 0, 1, min_col)

        total_ways = 0
        # Try placing each number from min_row to k in the current cell
        for num in range(min_row, k + 1):
            if num >= min_col:
                total_ways += dp(row, col + 1, min_row, num)
                total_ways %= MOD

        memo[(row, col, min_row, min_col)] = total_ways
        return total_ways

    return dp(0, 0, 1, 1)

